import{_ as o,C as s,o as r,c as i,j as t,a as n,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse('{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","frontmatter":{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:title","content":"Run video | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends."}]]},"headers":[],"relativePath":"features/run-video.md","filePath":"features/run-video.md","lastUpdated":1794596444000}'),l={name:"features/run-video.md"};function c(p,e,u,w,f,v){const a=s("Needs");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"run-video",tabindex:"-1"},[n("Run video "),t("a",{class:"header-anchor",href:"#run-video","aria-label":'Permalink to "Run video"'},"​")],-1)),h(a,{reporter:""}),e[1]||(e[1]=d('<p>A finished run has a <strong>Video</strong> tab, labelled with the number of tests that have a video (<strong>Video (12)</strong>). It plays the videos Playwright recorded for the run, one test after another, beside a checklist of the tests. A test is ticked as its video passes the end of the test, so you can follow a worker&#39;s run as it happened. The bar under the video has one block for each test, colored by its result. Click a test or the bar to jump there: while the video is paused it shows that frame and stays paused, and while it plays it keeps playing from there. The video, the bar and the marks under it fit the screen without scrolling the page; only the list of tests scrolls.</p><h2 id="group-by-worker-or-file" tabindex="-1">Group by Worker or File <a class="header-anchor" href="#group-by-worker-or-file" aria-label="Permalink to &quot;Group by Worker or File&quot;">​</a></h2><ul><li><strong>Worker</strong> plays one worker&#39;s tests in the order they ran. Pick the worker above the video.</li><li><strong>File</strong> plays every test in the order its file declares it, each marked with the worker it ran on. The tests ran in parallel, so this order is not the order they ran in.</li></ul><p>Only the final attempt of a test is listed. A test that has no video stays on the checklist and takes a small block on the bar. It is ticked as the reel moves on. The tab is off while the run is live.</p><h2 id="search-the-checklist" tabindex="-1">Search the checklist <a class="header-anchor" href="#search-the-checklist" aria-label="Permalink to &quot;Search the checklist&quot;">​</a></h2><p>The box above the checklist finds tests by their title, the way the <strong>Tests</strong> tab&#39;s search reads words (case and accents ignored, <code>&quot;…&quot;</code> for a phrase, <code>*</code> for anything, <code>-</code> to leave a word out). The list keeps the tests that match, with the matched words marked, and the line above it says how many match. Searching only hides rows: the video, the bar, the ticks and the marks stay as they were, and a click on a test still jumps there. The search stays when you pick another worker or group by file. The <strong>x</strong> in the box clears it.</p><h2 id="open-a-video-review-from-evidence" tabindex="-1">Open a video review from Evidence <a class="header-anchor" href="#open-a-video-review-from-evidence" aria-label="Permalink to &quot;Open a video review from Evidence&quot;">​</a></h2><p>On a finished execution that has a video, the Evidence header has an <strong>Open video review</strong> button, beside <strong>Open trace</strong>. It opens the video with the same bar and checklist as the Video tab, in a window that fills a narrow screen. The window&#39;s switch picks what plays, and it starts on <strong>This test</strong>:</p><ul><li><strong>This test</strong> plays only that test, from the start of its video to its end, and stops. The file&#39;s other tests stay on the checklist, dimmed, and are not played.</li><li><strong>Whole file</strong> plays the file&#39;s final attempts in declared order, each marked with its worker, and starts on this test.</li><li><strong>Its worker</strong> plays the tests of this test&#39;s worker, in the order they ran, and starts on this test. A sharded run keeps each shard&#39;s workers apart.</li></ul><p>In these two modes only the tests that play are ticked, and <strong>Play</strong> after the end starts again from this test. The opened test is marked <strong>This test</strong> in every mode. Closing the window stops the video.</p><p>Only final attempts that ran are in the file and worker reels. On an earlier attempt or a skipped test, This test plays its own video and the other two modes are off, with the reason shown under the switch. A run lists at most 2,000 tests with a video, so a test past that limit also keeps only This test.</p><h2 id="actions-under-the-video" tabindex="-1">Actions under the video <a class="header-anchor" href="#actions-under-the-video" aria-label="Permalink to &quot;Actions under the video&quot;">​</a></h2><p>Under the bar, a lane of marks shows what the playing test did and when: one mark for each click, double click, fill, type, key press, check, uncheck, select, hover and navigation, placed on the video where it happened. It shows on the Video tab and in the Evidence video review.</p><ul><li>Point at a mark, or move to it with the keyboard, to read the action and its locator, for example <code>Click getByRole(&#39;button&#39;, { name: &#39;Save&#39; })</code>. Choose a mark to go there; it plays on only if the video was playing.</li><li>An action that failed has a red mark.</li><li>Marks less than 28 px apart merge into one mark with a count, so every mark keeps its own hit area. Its tooltip lists them.</li><li>An action outside the video is shown at the nearest edge of the lane, with a note in its tooltip.</li><li>A test with more than 500 actions shows the first 500, and the lane says how many there are.</li></ul><p>The marks come from what the project already stores. A test with a <a href="./evidence.html">trace</a> uses the trace&#39;s actions, and any other test uses its step list, so there is nothing to switch on. A test with neither shows &quot;No recorded actions for this test&quot;. A test that recorded actions but not when it started shows &quot;This test did not record when it started, so its actions cannot be placed in the video&quot;, since there is nothing to place them by. A failed load is one muted line; the video plays either way.</p><p>Piwi does not show what a test typed. The server masks each action before it sends it, and a locator is shown as the test wrote it:</p><table tabindex="0"><thead><tr><th>Action</th><th>Shown</th></tr></thead><tbody><tr><td>Fill, type</td><td>The locator and &quot;typed N chars&quot;, never the text. &quot;typed text&quot;, with no count, for a password, card or code field, or when no field is named</td></tr><tr><td>Press</td><td>A named key or a shortcut, such as <code>Enter</code> or <code>Control+A</code>; a single character, alone or behind Shift or Alt, shows as &quot;a key&quot;</td></tr><tr><td>Navigate</td><td>The origin and path, without the query string, fragment or credentials; a path segment shaped like a token is hidden</td></tr><tr><td>Check, uncheck, select</td><td>The locator only, never the chosen option</td></tr></tbody></table><h2 id="when-there-are-no-videos" tabindex="-1">When there are no videos <a class="header-anchor" href="#when-there-are-no-videos" aria-label="Permalink to &quot;When there are no videos&quot;">​</a></h2><p>Most suites record video only for failing tests (<code>video: &#39;retain-on-failure&#39;</code>), so a run where nothing failed often has none. The tab is then disabled, with the tooltip &quot;no videos in this run&quot;. Set <code>video: &#39;on&#39;</code> in Playwright&#39;s <code>use</code> options to record every test. Videos can be large, so read <a href="/operate/storage.html#storage-management">storage cleanup</a> first.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a>: one failing execution, with its trace, screenshots and video</li><li><a href="/operate/storage.html#storage-management">Storage</a>: how long videos are kept</li></ul>',21))])}const y=o(l,[["render",c]]);export{k as __pageData,y as default};
